#!/usr/bin/env bash
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/.." && pwd)
SETTINGS="$ROOT/settings.json"
json_get() { node -e 'const fs=require("fs"); const data=JSON.parse(fs.readFileSync(process.argv[1],"utf8")); const key=process.argv[2]; let v=data; for (const p of key.split(".")) v=v[p]; if (typeof v === "object") console.log(JSON.stringify(v)); else console.log(v);' "$SETTINGS" "$1"; }
expand_path() { local value="$1"; if [[ "$value" == "~/"* ]]; then printf '%s/%s' "$HOME" "${value:2}"; else printf '%s' "$value"; fi; }
service_config() { expand_path "$(json_get paths.serviceConfig)"; }
api_key() { node -e 'const c=require(process.argv[1]); console.log(c.services[process.argv[2]].apiKey)' "$(service_config)" "$1"; }
DOWNLOAD_URI=${1:?usage: workflow/03-add-download.sh <download-uri> <movie|tv|category>}
KIND=${2:?usage: workflow/03-add-download.sh <download-uri> <movie|tv|category>}
case "$KIND" in movie) CATEGORY=radarr ;; tv) CATEGORY=tv-sonarr ;; *) CATEGORY="$KIND" ;; esac
DOWNLOAD_URL=$(json_get backends.downloadClient.url)
export DOWNLOAD_CLIENT_URL="$DOWNLOAD_URL"
DOWNLOAD_STAGING=$(json_get paths.downloadStaging)
curl -s -b /tmp/video_fetcher_download_cookies.txt -H "Referer: $DOWNLOAD_URL" -X POST "$DOWNLOAD_URL/api/v2/torrents/add" --data-urlencode "urls=$DOWNLOAD_URI" --data-urlencode "savepath=$DOWNLOAD_STAGING" --data-urlencode "category=$CATEGORY"
printf '{"ok":true,"category":"%s","savepath":"%s"}\n' "$CATEGORY" "$DOWNLOAD_STAGING"

#!/usr/bin/env bash
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/.." && pwd)
SETTINGS="$ROOT/settings.json"
json_get() { node -e 'const fs=require("fs"); const data=JSON.parse(fs.readFileSync(process.argv[1],"utf8")); const key=process.argv[2]; let v=data; for (const p of key.split(".")) v=v[p]; if (typeof v === "object") console.log(JSON.stringify(v)); else console.log(v);' "$SETTINGS" "$1"; }
expand_path() { local value="$1"; if [[ "$value" == "~/"* ]]; then printf '%s/%s' "$HOME" "${value:2}"; else printf '%s' "$value"; fi; }
service_config() { expand_path "$(json_get paths.serviceConfig)"; }
api_key() { node -e 'const c=require(process.argv[1]); console.log(c.services[process.argv[2]].apiKey)' "$(service_config)" "$1"; }
QUERY=${1:?usage: workflow/01-search-releases.sh <query>}
SEARCH_URL=$(json_get backends.releaseSearch.url)
SEARCH_KEY=$(api_key prowlarr)
ENCODED=$(node -e 'console.log(encodeURIComponent(process.argv.slice(1).join(" ")))' "$QUERY")
curl -s "$SEARCH_URL/api/v1/search?query=$ENCODED&type=search&limit=50" -H "X-Api-Key: $SEARCH_KEY" | node -e 'const fs=require("fs"); const rows=JSON.parse(fs.readFileSync(0,"utf8")||"[]"); const out=rows.map(r=>{const hash=r.infoHash || ((r.guid||"").match(/[A-Fa-f0-9]{40}/)||[])[0]; const downloadUri=r.magnetUrl || (hash ? `magnet:?xt=urn:btih:${hash}&dn=${encodeURIComponent(r.title||"")}` : r.downloadUrl || r.guid); return {title:r.title,sizeBytes:r.size,quality:r.quality?.quality?.name || r.quality || null,seeders:r.seeders,indexer:r.indexer,downloadUri,infoHash:hash || null};}); console.log(JSON.stringify(out,null,2));'

